'use strict';

const { S3Client, PutObjectCommand, HeadObjectCommand } = require('@aws-sdk/client-s3');
const { getSignedUrl } = require('@aws-sdk/s3-request-presigner');
const { AWS_REGION, S3_BUCKET, S3_ACCESS_KEY_ID, S3_SECRET_ACCESS_KEY, S3_PRESIGN_TTL } = require('../config/env');

const s3 = new S3Client({
  region: AWS_REGION,
  credentials: {
    accessKeyId: S3_ACCESS_KEY_ID,
    secretAccessKey: S3_SECRET_ACCESS_KEY,
  },
});

/**
 * Generates a presigned PUT URL for uploading an object to S3.
 * The key is generated by the caller (controller) and passed in — server owns the key, never the client.
 * @param {{ key: string, contentType: string }} options
 * @returns {Promise<{ uploadUrl: string, key: string, objectUrl: string }>}
 */
async function getPresignedPutUrl({ key, contentType }) {
  const command = new PutObjectCommand({
    Bucket: S3_BUCKET,
    Key: key,
    ContentType: contentType,
  });

  const uploadUrl = await getSignedUrl(s3, command, { expiresIn: S3_PRESIGN_TTL });
  const objectUrl = `https://${S3_BUCKET}.s3.${AWS_REGION}.amazonaws.com/${key}`;

  return { uploadUrl, key, objectUrl };
}

/**
 * Checks whether an object exists in S3 by issuing a HeadObject request.
 * @param {string} key
 * @returns {Promise<boolean>}
 */
async function objectExists(key) {
  try {
    await s3.send(new HeadObjectCommand({ Bucket: S3_BUCKET, Key: key }));
    return true;
  } catch (err) {
    // NotFound or NoSuchKey → object does not exist
    return false;
  }
}

module.exports = { getPresignedPutUrl, objectExists };
